package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        Complex c = new Complex(1.0, 2.0);
        assertTrue("Identity check failed", c.equals(c));
    }

    @Test
    public void testEquals_DifferentClass() {
        Complex c = new Complex(1.0, 2.0);
        assertFalse("Should return false for different class type", c.equals("Not a Complex object"));
        assertFalse("Should return false for null", c.equals(null));
    }

    @Test
    public void testEquals_NaN_BothNaN() {
        // Using Double.NaN to trigger isNaN logic
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(Double.NaN, Double.NaN);
        assertTrue("Two NaN complexes should be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_OneNaN_OneNotNaN() {
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(1.0, 2.0);
        assertFalse("NaN complex should not equal non-NaN complex", c1.equals(c2));
        assertFalse("Non-NaN complex should not equal NaN complex", c2.equals(c1));
    }

    @Test
    public void testEquals_Normal_EqualValues() {
        Complex c1 = new Complex(1.5, -3.0);
        Complex c2 = new Complex(1.5, -3.0);
        assertTrue("Complex numbers with same real and imaginary parts should be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_Normal_DifferentReal() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.1, 2.0);
        assertFalse("Complex numbers with different real parts should not be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_Normal_DifferentImaginary() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.0, 2.1);
        assertFalse("Complex numbers with different imaginary parts should not be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_InfiniteValues() {
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 2.0);
        Complex c2 = new Complex(Double.POSITIVE_INFINITY, 2.0);
        assertTrue("Infinite values should follow standard equality", c1.equals(c2));

        Complex c3 = new Complex(Double.NEGATIVE_INFINITY, 2.0);
        assertFalse("Different infinities should not be equal", c1.equals(c3));
    }
}
